import sys

class Node:
    __slots__ = ('val', 'left', 'right')
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.left = insert(root.left, val)
    else:
        root.right = insert(root.right, val)
    return root

def min_diff_bst(root):
    stack = []
    cur = root
    prev = None
    min_diff = float('inf')
    while stack or cur:
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        if prev is not None:
            diff = cur.val - prev
            if diff < min_diff:
                min_diff = diff
        prev = cur.val
        cur = cur.right
    return min_diff

def main():
    data = sys.stdin.read().split()
    if not data:
        print(0)
        return
    n = int(data[0])
    if n == 0:
        print(0)
        return
    vals = list(map(int, data[1:1+n]))
    root = None
    for v in vals:
        root = insert(root, v)
    ans = min_diff_bst(root)
    print(ans if ans != float('inf') else 0)

if __name__ == "__main__":
    main()
